{"path":"/Users/philosopher/active/autopipe/autopipe/tuning/__init__.py","content":""""AutoPipe Hyperparameter Tuning.

Comprehensive hyperparameter optimization supporting:
- Grid Search
- Random Search
- Bayesian Optimization (Optuna)
- Population Based Training (PBT)
- Multi-objective optimization
"""

from typing import Any, Callable, Dict, List, Optional, Union, Tuple
import numpy as np
from abc import ABC, abstractmethod
from dataclasses import dataclass
from enum import Enum
import json


class SearchStrategy(Enum):
    """Hyperparameter search strategies."""
    GRID = "grid"
    RANDOM = "random"
    BAYESIAN = "bayesian"
    PBT = "pbt"
    EVOLUTIONARY = "evolutionary"


@dataclass
class HyperparameterSpace:
    """Defines a hyperparameter search space."""
    name: str
    param_type: str  # "continuous", "discrete", "categorical"
    bounds: Optional[Tuple[float, float]] = None
    choices: Optional[List[Any]] = None
    log_scale: bool = False

    def sample(self, rng: Optional[np.random.RandomState] = None) -> Any:
        """Sample a value from this space."""
        if rng is None:
            rng = np.random

        if self.param_type == "categorical":
            return rng.choice(self.choices)

        elif self.param_type == "discrete":
            return rng.randint(self.bounds[0], self.bounds[1] + 1)

        elif self.param_type == "continuous":
            if self.log_scale:
                log_low, log_high = np.log(self.bounds[0]), np.log(self.bounds[1])
                return np.exp(rng.uniform(log_low, log_high))
            return rng.uniform(self.bounds[0], self.bounds[1])


@dataclass
class Trial:
    """Represents a single hyperparameter tuning trial."""
    trial_id: str
    params: Dict[str, Any]
    metrics: Dict[str, float] = None
    status: str = "pending"  # pending, running, completed, failed

    def __post_init__(self):
        if self.metrics is None:
            self.metrics = {}


class BaseTuner(ABC):
    """Abstract base class for hyperparameter tuners."""

    def __init__(
        self,
        param_space: Dict[str, HyperparameterSpace],
        objective_fn: Callable[[Dict[str, Any]], Dict[str, float]],
        n_trials: int = 100,
        n_workers: int = 1,
        direction: Union[str, List[str]] = "minimize",
        random_state: int = 42,
    ):
        self.param_space = param_space
        self.objective_fn = objective_fn
        self.n_trials = n_trials
        self.n_workers = n_workers
        self.direction = direction if isinstance(direction, list) else [direction]
        self.random_state = random_state
        self.rng = np.random.RandomState(random_state)

        self.trials: List[Trial] = []
        self.best_trial: Optional[Trial] = None
        self.study_id = f"study_{random_state}_{id(self)}"

    @abstractmethod
    def suggest_params(self, trial_id: str) -> Dict[str, Any]:
        """Suggest hyperparameters for a trial."""
        pass

    @abstractmethod
    def update(self, trial: Trial):
        """Update tuner state with trial results."""
        pass

    def optimize(self, callbacks: Optional[List[Callable]] = None) -> Trial:
        """Run hyperparameter optimization."""
