def continuous(
    low: float,
    high: float,
    log_scale: bool = False
) -> HyperparameterSpace:
    """Define a continuous parameter space."""
    return HyperparameterSpace(
        name="",
        param_type="continuous",
        bounds=(low, high),
        log_scale=log_scale
    )


def discrete(low: int, high: int) -> HyperparameterSpace:
    """Define a discrete parameter space."""
    return HyperparameterSpace(
        name="",
        param_type="discrete",
        bounds=(low, high)
    )


def categorical(choices: List[Any]) -> HyperparameterSpace:
    """Define a categorical parameter space."""
    return HyperparameterSpace(
        name="",
        param_type="categorical",
        choices=choices
    )
